import hinge = require( './index' );


// TESTS //

// The function returns a number...
{
	hinge( 1.0, 0.44, 0.5869 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	hinge( true, 0.44, 0.8975 ); // $ExpectError
	hinge( false, 0.44, 0.8975 ); // $ExpectError
	hinge( null, 0.44, 0.8975 ); // $ExpectError
	hinge( undefined, 0.44, 0.8975 ); // $ExpectError
	hinge( '5', 0.44, 0.8975 ); // $ExpectError
	hinge( [], 0.44, 0.8975 ); // $ExpectError
	hinge( {}, 0.44, 0.8975 ); // $ExpectError
	hinge( ( x: number ): number => x, 0.44, 0.8975 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	hinge( 1.0, true, 0.8975 ); // $ExpectError
	hinge( 1.0, false, 0.8975 ); // $ExpectError
	hinge( 1.0, null, 0.8975 ); // $ExpectError
	hinge( 1.0, undefined, 0.8975 ); // $ExpectError
	hinge( 1.0, '5', 0.8975 ); // $ExpectError
	hinge( 1.0, [], 0.8975 ); // $ExpectError
	hinge( 1.0, {}, 0.8975 ); // $ExpectError
	hinge( 1.0, ( x: number ): number => x, 0.8975 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	hinge( 1.0, 0.44, true ); // $ExpectError
	hinge( 1.0, 0.44, false ); // $ExpectError
	hinge( 1.0, 0.44, null ); // $ExpectError
	hinge( 1.0, 0.44, undefined ); // $ExpectError
	hinge( 1.0, 0.44, '5' ); // $ExpectError
	hinge( 1.0, 0.44, [] ); // $ExpectError
	hinge( 1.0, 0.44, {} ); // $ExpectError
	hinge( 1.0, 0.44, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	hinge(); // $ExpectError
	hinge( 1.0 ); // $ExpectError
	hinge( 1.0, 0.900 ); // $ExpectError
	hinge( 1.0, 0.900, 0.787, 5.0 ); // $ExpectError
}
